create extension if not exists pgcrypto;
create table if not exists public.radar_sources(id uuid primary key default gen_random_uuid(),name text not null,canonical_url text,source_type text,country_code text,access_method text,licence_notes text,update_frequency text,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.radar_signals(id uuid primary key default gen_random_uuid(),title text not null,summary text not null,source_url text not null,source_name text,source_type text,published_at timestamptz,discovered_at timestamptz not null default now(),country text,country_code text,city text,latitude double precision,longitude double precision,innovation_type text not null,educational_problem text,target_groups text[] default '{}',novelty smallint check(novelty between 1 and 5),maturity text not null default 'early_signal' check(maturity in('early_signal','experiment','pilot','scaling','established')),evidence_level text not null default 'none' check(evidence_level in('none','anecdotal','case','emerging','moderate','strong')),evidence_summary text,swiss_relevance text,swiss_application_hypothesis text,limitations text,tags text[] default '{}',metadata jsonb not null default '{}'::jsonb,status text not null default 'candidate' check(status in('candidate','reviewed','validated','archived')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index if not exists radar_signals_source_url_uidx on public.radar_signals(source_url);create index if not exists radar_signals_country_idx on public.radar_signals(country_code);create index if not exists radar_signals_type_idx on public.radar_signals(innovation_type);
create table if not exists public.radar_relations(id uuid primary key default gen_random_uuid(),from_signal_id uuid not null references public.radar_signals(id) on delete cascade,to_signal_id uuid not null references public.radar_signals(id) on delete cascade,relation_type text not null check(relation_type in('similar_to','related_to','inspired_by','evolved_into','same_cluster')),confidence numeric(4,3),rationale text,created_at timestamptz not null default now(),unique(from_signal_id,to_signal_id,relation_type));
create table if not exists public.radar_reviews(id uuid primary key default gen_random_uuid(),signal_id uuid not null references public.radar_signals(id) on delete cascade,reviewer_name text,reviewer_role text,educational_relevance text,evidence_judgement text,transferability text,notes text,created_at timestamptz not null default now());
alter table public.radar_sources enable row level security;alter table public.radar_signals enable row level security;alter table public.radar_relations enable row level security;alter table public.radar_reviews enable row level security;
